export default function ThereseOfLisieux({ p, detail }: PortraitProps) {
  return (
    <>
      <g transform={ART_TRANSFORM}>
        {/* Cloud bank. The drawn scallops are open contours, so the fill is cut */}
        <path {...p('cloud')} d={CLOUD_MASK} fillRule="evenodd" />

        {/* Halo ring (outer contour + inner hole, even-odd). */}
        <path {...p('halo')} d={HALO_MASK} fillRule="evenodd" />

        {/* Outer veil. */}
        <path {...p('mantle')} d={MANTLE_MASK} fillRule="evenodd" />

        {/* Cape and habit. */}
        <path {...p('robe')} d={ROBE_MASK} fillRule="evenodd" />

        {/* Coif and wimple framing the face. */}
        <path {...p('hair')} d={HAIR_MASK} fillRule="evenodd" />

        {/* Leaves and stems of the roses. */}
        <path {...p('garden')} d={GARDEN_MASK} fillRule="evenodd" />

        {/* Rose blooms. */}
        <path {...p('symbol')} d={SYMBOL_MASK} fillRule="evenodd" />

        {/* Crucifix. */}
        <path {...p('accent')} d={ACCENT_MASK} fillRule="evenodd" />

        {/* Face, neck and both hands. */}
        <path {...p('skin')} d={SKIN_MASK} fillRule="evenodd" />

        {/* Exact traced black line art; deliberately non-interactive. */}
        <path
          {...detail}
          {...ink}
          d={THERESE_LINE_ART}
          fillRule="evenodd"
          shapeRendering="geometricPrecision"
        />
      </g>
    </>
  );
}
